def build_records():
    rows=[]
    for band, gps in SIXTH_PAY_BANDS.items():
        for gp in gps:
            rows.append({'record_type':'PAY_STRUCTURE','pay_commission':'6th Pay Commission','pay_band':band,'grade_pay':int(gp),'pay_level':'','pay_matrix_cells':[],'increment_rule':'3% of Pay Band + Grade Pay; round as prescribed','increment_date_rule':'01 July','source_status':'Existing application master data'})
        if not gps:
            rows.append({'record_type':'PAY_STRUCTURE','pay_commission':'6th Pay Commission','pay_band':band,'grade_pay':'','pay_level':'','pay_matrix_cells':[],'increment_rule':'3% of Pay Band + Grade Pay; round as prescribed','increment_date_rule':'01 July','source_status':'Existing application master data'})
    for level,cells in PAY_MATRIX_7TH.items():
        rows.append({'record_type':'PAY_STRUCTURE','pay_commission':'7th Pay Commission','pay_band':'','grade_pay':'','pay_level':level,'pay_matrix_cells':cells,'increment_rule':'Next vertical cell in same Pay Level','increment_date_rule':'01 July','source_status':'Existing application master data'})
    for (yy,mm),due,cash,gpf in DA_7TH:
        rows.append({'record_type':'DA_RATE','pay_commission':'7th Pay Commission','effective_date':f'{yy:04d}-{mm:02d}-01','da_rate':due,'cash_da_rate':cash,'gpf_credit':gpf,'source_status':'Existing application arrear rule data'})
    for r in DA_6TH_OPTIONS:
        rows.append({'record_type':'DA_RATE_OPTION','pay_commission':'6th Pay Commission','da_rate':r,'source_status':'Existing application DA preset data; effective dates to be verified/expanded later'})
    for d,z,r in HRA_7TH:
        rows.append({'record_type':'HRA_RATE','pay_commission':'7th Pay Commission','effective_date':d,'city_class':z,'hra_rate':r,'source_status':'Existing application HRA rule data'})
    for d,z,r in HRA_6TH:
        rows.append({'record_type':'HRA_RATE','pay_commission':'6th Pay Commission','effective_date':d,'city_class':z,'hra_rate':r,'source_status':'Existing application HRA rule data'})
    return rows

FIELDS=[
 ('record_type','text'),('pay_commission','text'),('pay_band','text'),('grade_pay','number'),('pay_level','text'),('pay_matrix_cells','text'),('effective_date','text'),('city_class','text'),('da_rate','decimal'),('cash_da_rate','decimal'),('gpf_credit','boolean'),('hra_rate','decimal'),('increment_rule','text'),('increment_date_rule','text'),('source_status','text')
]

def main():
    SEED_FILE.parent.mkdir(parents=True,exist_ok=True)
    data={'version':'2026-10-06.1','locked':True,'fields':[{'field_name':n,'field_type':t} for n,t in FIELDS],'records':build_records()}
    SEED_FILE.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    print(SEED_FILE, len(data['records']))
if __name__=='__main__': main()
